import sys; sys.path.insert(0, '.')
import json, re
from phase0_v2.calibration.audit_helpers import measure_fix_errors
from phase0_v2.calibration._shared import load_records

records = load_records('phase0_v2/data/results/google_gemma-3-27b-it_results.jsonl')

def _is_valid_json_object_v2(text):
    t = text.strip()
    m = re.match(r'^```(?:json)?\s*\n(.*?)(?:\n```\s*)?$', t, re.DOTALL)
    if m: t = m.group(1).strip()
    if t.startswith('{'):
        try:
            parsed = json.loads(t)
            if isinstance(parsed, dict): return True
        except: 
            if re.search(r'"[^"]+"\s*:', t): return True
    fence_matches = re.findall(r'```(?:json)?\s*\n(.*?)(?:\n```)', text, re.DOTALL)
    unclosed = re.findall(r'```(?:json)?\s*\n(.*?)$', text, re.DOTALL)
    for block in fence_matches + unclosed:
        block = block.strip()
        if block.startswith('{'):
            try:
                parsed = json.loads(block)
                if isinstance(parsed, dict): return True
            except:
                if re.search(r'"[^"]+"\s*:', block): return True
    return False

fix = measure_fix_errors(records, 'json_only_vs_plain', _is_valid_json_object_v2, lambda r: not _is_valid_json_object_v2(r))
print(f"old: {fix['old_labels']}")
print(f"new: {fix['new_labels']}")
print(f"error_pct: {fix['error_pct']:.2f}%")
print(f"changed: {fix['changed']} labels")
